//! UTC → TAI → TT → TDB checked against ERFA (open-source SOFA).
//! Fixture: tests/fixtures/time_erfa.csv, generated by tools/fixtures/gen_time_erfa.py.

use sim_core::time::{self, UtcDateTime};

struct Row {
    utc: String,
    dat: f64,
    tai: (i64, f64),
    tt: (i64, f64),
    tdb: (i64, f64),
}

fn rows() -> Vec<Row> {
    include_str!("fixtures/time_erfa.csv")
        .lines()
        .skip(1)
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            let f: Vec<&str> = l.split(',').collect();
            let p = |i: usize| -> (i64, f64) { (f[i].parse().unwrap(), f[i + 1].parse().unwrap()) };
            Row {
                utc: f[0].to_string(),
                dat: f[1].parse().unwrap(),
                tai: p(2),
                tt: p(4),
                tdb: p(6),
            }
        })
        .collect()
}

fn diff((s1, f1): (i64, f64), (s2, f2): (i64, f64)) -> f64 {
    (s1 - s2) as f64 + (f1 - f2)
}

#[test]
fn leap_second_offsets_match_erfa() {
    for r in rows() {
        let u = UtcDateTime::parse_iso(&r.utc).unwrap();
        assert_eq!(
            time::tai_minus_utc(u.mjd_day()).unwrap() as f64,
            r.dat,
            "{}",
            r.utc
        );
    }
}

#[test]
fn tai_and_tt_match_erfa_to_a_nanosecond() {
    // ERFA's two-part JD limits it to ~1e-11 s; anything above 1 ns is a real bug.
    for r in rows() {
        let u = UtcDateTime::parse_iso(&r.utc).unwrap();
        let tai = time::utc_to_tai(&u).unwrap();
        let tt = time::tai_to_tt(tai);
        assert!(
            diff(tai.parts(), r.tai).abs() < 1e-9,
            "TAI {}: {}",
            r.utc,
            diff(tai.parts(), r.tai)
        );
        assert!(
            diff(tt.parts(), r.tt).abs() < 1e-9,
            "TT {}: {}",
            r.utc,
            diff(tt.parts(), r.tt)
        );
    }
}

#[test]
fn tdb_matches_erfa_dtdb_within_series_accuracy() {
    // USNO Circular 179 eq. 2.6 is quoted at ~10 µs versus the full
    // Fairhead–Bretagnon series that eraDtdb implements.
    let mut worst = 0.0f64;
    for r in rows() {
        let u = UtcDateTime::parse_iso(&r.utc).unwrap();
        let tdb = time::utc_to_tdb(&u).unwrap();
        let d = diff(tdb.tdb_parts(), r.tdb).abs();
        worst = worst.max(d);
        assert!(d < 10e-6, "TDB {}: {d:e} s", r.utc);
    }
    eprintln!("worst |TDB − ERFA| = {worst:.3e} s");
}

#[test]
fn erfa_epochs_roundtrip_back_to_the_same_utc() {
    for r in rows() {
        let u = UtcDateTime::parse_iso(&r.utc).unwrap();
        let back = time::tdb_to_utc(time::utc_to_tdb(&u).unwrap()).unwrap();
        assert_eq!(back.to_iso(6), u.to_iso(6), "{}", r.utc);
    }
}
